def attrs(*names, sale=('Sale', 'Rent')):
    return [ATTR['for'](list(sale)) if n == 'for' else ATTR[n] for n in names]


def L(title, slug, cat, kind, loc, price, attrs_, short, featured=False, badge='', note='', closed=False, gallery=None, highlights=None):
    return {'title': title, 'slug': slug, 'cat': cat, 'kind': kind, 'loc': loc, 'price': price, 'attrs': attrs_, 'short': short, 'featured': featured,
            'badge': badge, 'note': note, 'closed': closed, 'gallery': gallery, 'highlights': highlights or []}


def T(name, role, bio):
    return {'name': name, 'role': role, 'bio': bio}


def S(icon, title, desc):
    return {'icon': icon, 'title': title, 'description': desc}


